// te — తెలుగు.
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// TOM: **మీరు**, pela quarta vez o mesmo raciocínio — e já dá para chamar de padrão. O télugo tem
// **నువ్వు**, que é de intimidade (irmão, amigo de infância, criança) e com quem acabou de chegar soa
// atrevido, não próximo. మీరు é o neutro entre adultos, é o que todo aplicativo usa, e não carrega a
// distância do "senhor". Malaio, urdu, persa, japonês e télugo: em todos, a forma íntima seria o erro
// OPOSTO ao de tratar por senhor, e igualmente errado.
//
// ===================================================================================================
// OS ALGARISMOS SÃO LATINOS, MAS O AGRUPAMENTO NÃO É O NOSSO — e isto parece defeito e não é.
//
//   Intl.NumberFormat('pt-BR').format(1234567)  →  1.234.567
//   Intl.NumberFormat('te').format(1234567)     →  12,34,567
//
// É o sistema indiano: depois do primeiro grupo de três, os separadores vêm de DOIS em dois (lakh,
// crore). Quem vir "12,34,567" na tela e achar que a vírgula caiu no lugar errado vai "consertar" uma
// coisa certa. O Intl faz isso sozinho; não há nada a escrever à mão.
// ===================================================================================================
//
// A ESCRITA TEM FONTE PRÓPRIA (Noto Sans Telugu), e ela é buscada só quando alguém escolhe télugo —
// ver FONTE_DA_ESCRITA em idiomas.ts. Sem ela, a tela vira quadradinho. Foi medido: as letras saem
// desenhadas, e nada estourou a caixa nas onze abas.
//
// VOCABULÁRIO, decidido uma vez: comunidade = కమ్యూనిటీ, canal = ఛానెల్, sala/canal de voz =
// వాయిస్ ఛానెల్, గది quando é a sala onde se está, mensagem = సందేశం, senha = పాస్‌వర్డ్,
// lixeira = చెత్తబుట్ట, tópico = థ్రెడ్, insígnia = బ్యాడ్జ్,
// selo (os quatro caracteres da comunidade) = ట్యాగ్, avatar = ప్రొఫైల్ చిత్రం,
// transmissão de tela = స్క్రీన్ షేర్.
//
// Gerado por: node scripts/idiomas.mjs --novo te

