  'Como administrador, você pode remover membros que não são administradores.': 'నిర్వాహకుడిగా, నిర్వాహకులు కాని సభ్యులను మీరు తొలగించవచ్చు.',
  'Como dono, você escolhe quem administra e pode remover qualquer pessoa.': 'యజమానిగా, ఎవరు నిర్వహించాలో మీరు ఎంచుకుంటారు, ఎవరినైనా తొలగించవచ్చు.',
