  'Comunidades': 'కమ్యూనిటీలు',
  'Confete, fogos e corações que qualquer pessoa da sala pode mandar. Desligue se o seu computador engasgar durante a chamada — desligado, você não vê nem manda.': 'కాగితపు ముక్కలు, బాణసంచా, హృదయాలు — గదిలో ఎవరైనా పంపగలరు. కాల్ సమయంలో మీ కంప్యూటర్ నెమ్మదిస్తే ఆపేయండి. ఆపేశాక మీరు చూడలేరు, పంపలేరు.',
