  'É o nome que todos veem no Syden. Para entrar e nas menções com @, continua valendo o nome da conta.': 'Syden‌లో అందరికీ కనిపించే పేరు ఇదే. లాగిన్‌కి, @ తో ప్రస్తావనలకి ఖాతా పేరే కొనసాగుతుంది.',
