  'Desconecta o Syden em todos os outros computadores e celulares. Você continua conectado aqui.': 'మిగతా అన్ని కంప్యూటర్లు, ఫోన్లలో Syden నుంచి లాగ్ అవుట్ చేస్తుంది. ఇక్కడ మీరు లాగిన్‌లోనే ఉంటారు.',
