  'Desconectar': 'లాగ్ అవుట్',
  'Descrição': 'వివరణ',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.': 'ఆఫ్‌లో ఉంటే, గదిలో ఉన్నవారి స్క్రీన్ షేర్ ఒక ఆహ్వానంలా మాత్రమే కనిపిస్తుంది; మీరు చూడు నొక్కినప్పుడే డౌన్‌లోడ్ మొదలవుతుంది. దీనివల్ల ఇంటర్నెట్, ప్రాసెసర్ రెండూ ఆదా అవుతాయి — ముఖ్యంగా గది నిండుగా ఉన్నప్పుడు.',
