  'Deste servidor': 'ఈ సర్వర్‌ది',
  'Diga o e-mail da sua conta e mandamos um link para escolher outra.': 'మీ ఖాతా ఇమెయిల్ చెప్పండి; కొత్త పాస్‌వర్డ్ ఎంచుకునే లింక్ పంపుతాం.',
  'Digite sua senha para confirmar': 'ధృవీకరణ కోసం మీ పాస్‌వర్డ్ టైప్ చేయండి',
  'Disponível': 'అందుబాటులో',
  'Do laranja ao vermelho, como carvão aceso.': 'నారింజ నుంచి ఎరుపు వరకు — మండుతున్న బొగ్గులా.',
  'Dois emojis com o mesmo nome: cada um precisa do seu.': 'ఒకే పేరుతో రెండు ఎమోజీలు: ఒక్కొక్కదానికి సొంత పేరు కావాలి.',
  'Dono': 'యజమాని',
  'Dono da comunidade': 'కమ్యూనిటీ యజమాని',
  'Dourado com brilho que passa devagar.': 'బంగారు రంగు — మెరుపు నెమ్మదిగా దాటిపోతుంది.',
  'Durante uma chamada, esse botão toca estes sons para todos na sala. Instale pacotes prontos ou envie os seus; o que é seu favorito fica na frente do painel.': 'కాల్ సమయంలో ఈ బటన్ ఈ శబ్దాలను గదిలోని అందరికీ వినిపిస్తుంది. సిద్ధంగా ఉన్న ప్యాక్‌లను పెట్టుకోండి లేదా మీ శబ్దాలను పంపండి; మీరు ఇష్టమైనదిగా గుర్తించినది ముందు ఉంటుంది.',
  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.': 'కమ్యూనిటీలోకి వచ్చినవారు మొదట చూసేది ఇదే — ఒక్కసారి మాత్రమే. ఇది లేకపోతే నేరుగా ఛానెల్‌ల జాబితాలోకి వెళ్తారు.',
  'É assim que os outros veem você na lista e nas conversas.': 'జాబితాలో, సంభాషణల్లో ఇతరులు మిమ్మల్ని ఇలా చూస్తారు.',
