  'É o seu único jeito de entrar. Defina uma senha antes de desligar.': 'లోపలికి రావడానికి ఇదొక్కటే మార్గం. ఆఫ్ చేసే ముందు ఒక పాస్‌వర్డ్ పెట్టండి.',
