  'Escolha aqui a língua do Syden. Vale na hora, só para você, e fica guardada neste computador.': 'Syden భాషను ఇక్కడ ఎంచుకోండి. వెంటనే అమలవుతుంది, మీకు మాత్రమే వర్తిస్తుంది, ఈ కంప్యూటర్‌లో భద్రంగా ఉంటుంది.',
  'Escolha o selo': 'ట్యాగ్‌ను ఎంచుకోండి',
  'Escolha quem entra. Com mais de uma pessoa, vira uma conversa em grupo.': 'ఎవరు రావాలో ఎంచుకోండి. ఒకరి కంటే ఎక్కువ మంది ఉంటే అది గ్రూప్ సంభాషణ అవుతుంది.',
