  'Online agora: {n}': 'ఇప్పుడు ఆన్‌లైన్: {n}',
  'Os números aparecem no alto da lista de canais, para todo mundo, e mudam sozinhos.': 'సంఖ్యలు ఛానెల్ జాబితా పైన అందరికీ కనిపిస్తాయి, వాటంతట అవే మారుతాయి.',
  'Criar uma sala para cada pessoa que entrar': 'లోపలికి వచ్చే ప్రతి ఒక్కరికీ ఒక గది సృష్టించు',
  'Entre para criar a sua sala': 'మీ సొంత గది కోసం లోపలికి రండి',
