  'Quantas pessoas cabem (0 = sem limite)': 'ఎంతమంది పడతారు (0 = పరిమితి లేదు)',
  'Canal de destaques': 'ప్రత్యేక సందేశాల ఛానెల్',
  'Destaques': 'ప్రత్యేకాలు',
  'Estrelas necessárias': 'అవసరమైన నక్షత్రాలు',
  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'ఒక సందేశానికి తగినన్ని ⭐ నక్షత్రాలు వచ్చినప్పుడు Syden దాన్ని ప్రత్యేక సందేశాల ఛానెల్‌లో పోస్ట్ చేస్తుంది. రాసినవారి సొంత నక్షత్రం లెక్కలోకి రాదు, సందేశాన్ని తొలగిస్తే ప్రత్యేకమైనదీ తొలగిపోతుంది.',
  '🎉 Resultado do sorteio de {premio}: {vencedores}. Parabéns!': '🎉 {premio} లాటరీ ఫలితం: {vencedores}. అభినందనలు!',
  '🎉 Sorteio: {premio}! Reaja com 🎉 para participar. O resultado sai em {quando}.': '🎉 లాటరీ: {premio}! పాల్గొనడానికి 🎉 తో స్పందించండి. ఫలితం {quando}న వస్తుంది.',
  'Começar o sorteio': 'లాటరీ మొదలుపెట్టండి',
  'Encerrar agora': 'ఇప్పుడే ముగించండి',
  'Ganhadores': 'బహుమతుల సంఖ్య',
  'Ninguém participou.': 'ఎవరూ పాల్గొనలేదు.',
  'Novo sorteio': 'కొత్త లాటరీ',
  'O sorteio de {premio} terminou sem participantes.': '{premio} లాటరీ పాల్గొనేవారు లేకుండా ముగిసింది.',
  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden ఛానెల్‌లో బహుమతిని ప్రకటిస్తుంది, పాల్గొనాలనుకునేవారు 🎉 తో స్పందిస్తారు. నిర్ణయించిన సమయానికి స్పందించినవారిలో నుంచి లాటరీ తీసి ఫలితాన్ని పోస్ట్ చేస్తుంది.',
  'Participantes: {n}': 'పాల్గొన్నవారు: {n}',
