  'Terminou em {quando}': 'ముగిసింది {quando}',
  'Aniversário': 'పుట్టినరోజు',
  'Aniversários': 'పుట్టినరోజులు',
  'Canal dos parabéns': 'శుభాకాంక్షల ఛానెల్',
  'Dia': 'రోజు',
  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'ఈ రోజు {pessoa} పుట్టినరోజు! 🎉 జన్మదిన శుభాకాంక్షలు!',
  'Mês': 'నెల',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'తేదీ నమోదు చేసినవారి పుట్టినరోజున Syden ఎంచుకున్న ఛానెల్‌లో శుభాకాంక్షలు పోస్ట్ చేస్తుంది. పేరుకు బదులు {pessoa} వాడండి.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'రోజు, నెల మాత్రమే, సంవత్సరం ఎప్పుడూ కాదు. పుట్టినరోజులు ప్రకటించే కమ్యూనిటీలు ఆ రోజే శుభాకాంక్షలు చెబుతాయి. ఇది ఐచ్ఛికం, ఎప్పుడైనా తొలగించవచ్చు.',
  'Texto dos parabéns': 'శుభాకాంక్షల పాఠం',
  'Agendar': 'షెడ్యూల్ చేయి',
  'Apagar a mensagem agendada': 'షెడ్యూల్ చేసిన సందేశాన్ని తొలగించు',
  'Canal': 'ఛానెల్',
  'Combinado: lembro você em {tempo}.': 'సరే: {tempo}లో మీకు గుర్తు చేస్తాను.',
