  'Na hora marcada, o Syden publica o texto no canal. Dá para repetir todo dia ou toda semana.': 'నిర్ణయించిన సమయానికి Syden ఛానెల్‌లో పాఠాన్ని పోస్ట్ చేస్తుంది. ప్రతిరోజు లేదా ప్రతివారం పునరావృతం చేయవచ్చు.',
  'Nova mensagem agendada': 'కొత్త షెడ్యూల్ సందేశం',
  'O que o Syden publica': 'Syden ఏమి పోస్ట్ చేస్తుంది',
  'Quando': 'ఎప్పుడు',
  'Repetir': 'పునరావృతం',
  'Texto da mensagem agendada': 'షెడ్యూల్ సందేశ పాఠం',
  'Toda semana': 'ప్రతివారం',
  'Todo dia': 'ప్రతిరోజు',
  'Uma vez': 'ఒకసారి',
  'Alguém escreve o comando no começo de uma mensagem, como !regras, e o Syden responde no canal com o texto que você cadastrar. Use {pessoa} para o nome de quem pediu e {comunidade} para o nome da comunidade.': 'ఎవరైనా సందేశం మొదట్లో !regras లాంటి కమాండ్ రాస్తే, మీరు నమోదు చేసిన పాఠంతో Syden ఛానెల్‌లో జవాబిస్తుంది. అడిగినవారి పేరుకు {pessoa}, కమ్యూనిటీ పేరుకు {comunidade} వాడండి.',
