  'Você está em silêncio em {comunidade} até {hora}.': '{comunidade}లో మీరు {hora} వరకు నిశ్శబ్ద మోడ్‌లో ఉన్నారు.',
  'Você está em silêncio nesta comunidade até {hora}.': 'ఈ కమ్యూనిటీలో మీరు {hora} వరకు నిశ్శబ్ద మోడ్‌లో ఉన్నారు.',
  'Você recebeu uma advertência em {comunidade}: {motivo}': '{comunidade}లో మీకు హెచ్చరిక వచ్చింది: {motivo}',
  'Barrar excesso de mensagens (mais de 5 em 10 segundos)': 'అతిగా సందేశాలను ఆపు (10 సెకన్లలో 5 కంటే ఎక్కువ)',
  'Bloquear links nas mensagens': 'సందేశాల్లో లింక్‌లను నిరోధించు',
  'Desligado': 'ఆఫ్',
  'Modo lento': 'నెమ్మది మోడ్',
  'Modo lento de {canal}': '{canal} నెమ్మది మోడ్',
  'Modo lento: uma mensagem a cada {tempo}.': 'నెమ్మది మోడ్: ప్రతి {tempo}కి ఒక సందేశం.',
  'Palavras proibidas': 'నిషేధిత పదాలు',
  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'ఛానెల్‌లో ప్రతి ఒక్కరూ సందేశాల మధ్య ఎంత సేపు ఆగాలి.',
  'Regras': 'నియమాలు',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'సందేశం కనిపించే ముందు Syden తానే అమలు చేసే నియమాలు. నిర్వాహకులకు వర్తించవు. నిరోధించిన సందేశం కారణంతో రాసినవారికే తిరిగి వెళ్తుంది, వేరెవరూ చూడరు.',
  'Salvo.': 'సేవ్ అయింది.',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'పంక్తికి ఒకటి. యాస చిహ్నాలు, పెద్ద అక్షరాల తేడా లేకుండా పూర్తి పదమే లెక్క: ఒక పదాన్ని నిషేధించడం దాన్ని మాత్రమే కలిగి ఉన్న పొడవైన పదాన్ని నిరోధించదు.',
  '{faltam} pontos para o nível {proximo}.': 'స్థాయి {proximo}కి {faltam} పాయింట్లు మిగిలాయి.',
  'Adicionar recompensa': 'బహుమతి జోడించు',
  'Cada mensagem vale pontos (uma por minuto), e cada minuto numa sala com mais alguém também. Quem sobe de nível recebe um aviso só para si.': 'ప్రతి సందేశానికి పాయింట్లు (నిమిషానికి ఒకటి), వేరొకరితో గదిలో గడిపే ప్రతి నిమిషానికీ కూడా. స్థాయి పెరిగినవారికి మాత్రమే నోటిఫికేషన్ వస్తుంది.',
