  'Mostrar a minha própria câmera': 'నా సొంత కెమెరాను చూపించు',
  'Muda como os outros ouvem você na chamada. Vale na hora, dá para trocar durante a conversa — e acaba quando você sai da sala: na próxima você entra com a sua voz.': 'కాల్‌లో ఇతరులు మిమ్మల్ని ఎలా వింటారో మారుస్తుంది. వెంటనే అమలవుతుంది, సంభాషణ మధ్యలోనూ మార్చవచ్చు — గది నుంచి బయటికి వెళ్ళగానే ముగుస్తుంది: తర్వాతిసారి మీ సొంత గొంతుతోనే వస్తారు.',
  'Mudar a largura de {barra}': '{barra} వెడల్పును మార్చు',
  'Mudar esta tela': 'ఈ తెరను మార్చు',
  'Muita gente procurando GIF agora. Tente de novo daqui a pouco.': 'ఇప్పుడు చాలామంది GIF వెతుకుతున్నారు. కాసేపటి తర్వాత మళ్ళీ ప్రయత్నించండి.',
  'Nada digno de nota até agora.': 'ఇప్పటివరకు చెప్పుకోదగినది ఏమీ లేదు.',
  'Nada é baixado enquanto você não abrir': 'మీరు తెరిచే వరకు ఏదీ డౌన్‌లోడ్ కాదు',
  'Nada faltando: o pacote está completo.': 'ఏమీ తక్కువ లేదు: ప్యాక్ పూర్తిగా ఉంది.',
  'Nada na lixeira.': 'చెత్తబుట్ట ఖాళీ.',
  'Nada registrado ainda. Só aparecem aqui as ações com poder sobre os outros.': 'ఇంకా ఏమీ నమోదు కాలేదు. ఇతరులపై అధికారం ఉన్న చర్యలు మాత్రమే ఇక్కడ కనిపిస్తాయి.',
  'Não chegou? Veja também a caixa de spam.': 'రాలేదా? స్పామ్ ఫోల్డర్ కూడా చూడండి.',
  'Não dá para desfazer.': 'దీన్ని వెనక్కి తీసుకోలేరు.',
  'Não deu para falar com o GIPHY agora.': 'ఇప్పుడు GIPHYతో సంప్రదించలేకపోయాం.',
  'Não deu para fechar o clipe agora. Tente de novo em alguns segundos.': 'ఇప్పుడు క్లిప్ పూర్తి కాలేదు. కొన్ని సెకన్ల తర్వాత మళ్ళీ ప్రయత్నించండి.',
  'Não deu para salvar o selo.': 'ట్యాగ్‌ను భద్రపరచలేకపోయాం.',
  'Não deu para tirar o selo.': 'ట్యాగ్‌ను తీసేయలేకపోయాం.',
  'Não deu para trazer o canal de volta.': 'ఛానెల్‌ను తిరిగి తేలేకపోయాం.',
  'Não há transmissão para clipar agora.': 'ఇప్పుడు క్లిప్ చేయడానికి స్క్రీన్ షేర్ ఏదీ లేదు.',
  'Não para nunca': 'ఎప్పుడూ ఆగదు',
  'Não perturbe': 'కలవరపెట్టవద్దు',
  'Não se compra: conquista-se.': 'కొనేది కాదు: సాధించేది.',
  'Nebulosa': 'నిహారిక',
  'Nenhum GIF para essa busca.': 'ఈ వెతుకులాటకు GIF ఏదీ లేదు.',
  'Nenhum pacote ainda. Monte o primeiro com imagens suas, ou publique os emojis que esta comunidade já tem.': 'ఇంకా ప్యాక్ ఏదీ లేదు. మీ చిత్రాలతో మొదటిది తయారుచేయండి, లేదా ఈ కమ్యూనిటీలో ఉన్న ఎమోజీలను ప్రచురించండి.',
  'Nenhum som com esse nome.': 'ఆ పేరుతో శబ్దం ఏదీ లేదు.',
  'Nenhuma denúncia até agora.': 'ఇప్పటివరకు ఫిర్యాదు ఏదీ లేదు.',
  'Nenhuma música ainda. Suba um arquivo que você tenha aí para a turma cantar.': 'ఇంకా పాట ఏదీ లేదు. మీ దగ్గర ఉన్న ఫైల్‌ను అప్‌లోడ్ చేయండి — అందరూ కలిసి పాడొచ్చు.',
  'Ninguém abriu a sua transmissão ainda. O Syden só codifica a imagem quando alguém assiste — por isso não há números aqui.': 'మీ స్క్రీన్ షేర్‌ను ఇంకా ఎవరూ తెరవలేదు. ఎవరైనా చూస్తున్నప్పుడే Syden చిత్రాన్ని ఎన్‌కోడ్ చేస్తుంది — అందుకే ఇక్కడ సంఖ్యలు లేవు.',
  'Ninguém com a palavra ainda': 'మాట్లాడే హక్కు ఇంకా ఎవరికీ లేదు',
  'Ninguém é avisado de que foi bloqueado.': 'నిరోధించినట్టు ఎవరికీ తెలియజేయబడదు.',
  'Ninguém entrou em chamada este mês ainda.': 'ఈ నెలలో ఇంకా ఎవరూ కాల్‌లోకి రాలేదు.',
  'Ninguém mais nesta comunidade ainda.': 'ఈ కమ్యూనిటీలో ఇంకా ఎవరూ లేరు.',
  'Ninguém na chamada — seja o primeiro': 'కాల్‌లో ఎవరూ లేరు — మీరే మొదటివారు కండి',
  'Ninguém para sugerir por enquanto — entre numa comunidade para conhecer gente.': 'ప్రస్తుతం సూచించడానికి ఎవరూ లేరు — మనుషులను కలవడానికి ఏదైనా కమ్యూనిటీలో చేరండి.',
  'Ninguém respondeu neste tópico ainda.': 'ఈ థ్రెడ్‌లో ఇంకా ఎవరూ జవాబివ్వలేదు.',
