  'Nova senha': 'కొత్త పాస్‌వర్డ్',
  'Dia e noite': 'పగలు మరియు రాత్రి',
  'O avatar limpo, como sempre foi.': 'అలంకారం లేని ప్రొఫైల్ చిత్రం — ఎప్పటిలాగే.',
  'O canal sai da vista de todos com as mensagens dentro. Dá para trazer de volta por {dias} dias, em Configurações → Comunidade → Lixeira.': 'ఛానెల్ లోపలి సందేశాలతో సహా అందరి కంటికి కనిపించకుండా పోతుంది. {dias} రోజుల వరకు సెట్టింగ్‌లు → కమ్యూనిటీ → చెత్తబుట్ట నుంచి తిరిగి తేవచ్చు.',
  'O cartão liso.': 'సాదా కార్డు.',
  'O céu inteiro girando bem devagar.': 'ఆకాశం మొత్తం చాలా నెమ్మదిగా తిరుగుతూ.',
  'O navegador bloqueou as notificações deste site. Libere no cadeado ao lado do endereço e recarregue a página.': 'ఈ సైట్ నోటిఫికేషన్‌లను బ్రౌజర్ నిరోధించింది. చిరునామా పక్కనున్న తాళం గుర్తు నుంచి అనుమతించి, పేజీని మళ్ళీ లోడ్ చేయండి.',
  'o nome exato da pessoa': 'ఆ వ్యక్తి సరైన పేరు',
  'O nome muda de cor devagar.': 'పేరు నెమ్మదిగా రంగు మారుతుంది.',
  'O que aconteceu?': 'ఏమి జరిగింది?',
  'O que dizer': 'ఏమి చెప్పాలి',
  'O que tem dentro': 'లోపల ఏమి ఉంది',
  'O que tem dentro do pacote': 'ప్యాక్ లోపల ఏమి ఉంది',
  'O que vamos jogar hoje?': 'ఈరోజు ఏమి ఆడదాం?',
  'O que você fez a respeito?': 'దాని గురించి మీరు ఏమి చేశారు?',
  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.': 'మొదటి మైలురాయిని చేరుకున్నప్పుడు ట్యాగ్ ఇక్కడ కనిపిస్తుంది. అప్పటివరకు దాగి ఉంటుంది — అక్కడికి చేరడమే దాని అర్థం.',
  'O selo desta comunidade é': 'ఈ కమ్యూనిటీ ట్యాగ్:',
  'O som chega quando você abre esta transmissão.': 'మీరు ఈ స్క్రీన్ షేర్‌ను తెరిచినప్పుడు శబ్దం వస్తుంది.',
  'O survival do Léo': 'లియో సర్వైవల్ సర్వర్',
  'O Syden já sabe escrever em qualquer uma destas línguas — falta a tradução dos textos. Enquanto ela não chega, o que não estiver traduzido aparece em português, e as letras de cada alfabeto aparecem certas, sem quadradinhos.': 'ఈ భాషల్లో ఏదైనా రాయడం Sydenకు తెలుసు — అనువాదం మాత్రమే మిగిలింది. అది వచ్చేవరకు, అనువదించనిది పోర్చుగీస్‌లో కనిపిస్తుంది, ప్రతి లిపి అక్షరాలూ సరిగ్గా కనిపిస్తాయి — చతురస్రాలు కాదు.',
  'O Syden vai ficar fora do ar por uns 10 minutos para uma atualização.': 'నవీకరణ కోసం Syden సుమారు 10 నిమిషాలు అందుబాటులో ఉండదు.',
  'Observação': 'గమనిక',
  'Oceania': 'ఓషియానియా',
  'Oceano': 'మహాసముద్రం',
  'Offline': 'ఆఫ్‌లైన్',
  'Olhe o seu e-mail': 'మీ ఇమెయిల్ చూడండి',
  'Opções': 'ఎంపికలు',
  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.': 'కింది మైలురాళ్ళను ఒక్కరే చేరుకోలేని విధంగా ఎంచారు — ప్రతిదానికీ కాలక్రమేణా ఒకరి కంటే ఎక్కువ మంది కావాలి.',
  'Os outros idiomas': 'ఇతర భాషలు',
  'Os outros passam a ouvir o efeito na hora. Você continua sem se escutar.': 'ఇతరులకు ప్రభావం వెంటనే వినిపిస్తుంది. మీకు మాత్రం మీ గొంతు వినిపించదు.',
  'ou': 'లేదా',
