  'Pronto: só este aparelho continua conectado.': 'అయింది: ఇప్పుడు ఈ పరికరం మాత్రమే లాగిన్‌లో ఉంది.',
  'Pronto. Quem entrar agora vai ver isto.': 'అయింది. ఇప్పటి నుంచి వచ్చేవారికి ఇది కనిపిస్తుంది.',
  'Qualidade do compartilhamento de tela': 'స్క్రీన్ షేరింగ్ నాణ్యత',
  'Quatro caracteres, um ícone e uma cor que aparecem ao lado do nome de quem é daqui.': 'నాలుగు అక్షరాలు, ఒక చిహ్నం, ఒక రంగు — ఇక్కడి వారి పేరు పక్కన కనిపిస్తాయి.',
