  'Aniversário do Syden': "Syden పుట్టినరోజు",
  'Hoje é aniversário do Syden!': "ఈ రోజు Syden పుట్టినరోజు!",
  'O Syden nasceu em {data}. Valeu por fazer parte desta história.': "Syden {data}న పుట్టింది. ఈ కథలో భాగమైనందుకు ధన్యవాదాలు.",
  'Quem mais cantou': "ఎవరు ఎక్కువగా పాడారు",
  'Mais cantadas': "ఎక్కువగా పాడినవి",
  'Músicas cantadas: {n}': "పాడిన పాటలు: {n}",
  'Ninguém cantou ainda. Conta quando alguém põe uma música com a turma na sala.': "ఇంకా ఎవరూ పాడలేదు. బృందం గదిలో ఉన్నప్పుడు ఎవరైనా పాట పెడితే లెక్కిస్తారు.",
  'Idiomas': "భాషలు",
  'Idiomas falados': "మాట్లాడే భాషలు",
  'Idiomas em estudo': "నేర్చుకుంటున్న భాషలు",
  'Aparece no seu cartão de perfil, para quem fala um idioma achar quem o estuda. É opcional.': "నీ ప్రొఫైల్ కార్డ్‌పై కనిపిస్తుంది, ఒక భాష మాట్లాడేవారు దాన్ని నేర్చుకునేవారిని కనుగొనడానికి. ఐచ్ఛికం.",
  'Feliz aniversário, {nome}!': 'పుట్టినరోజు శుభాకాంక్షలు, {nome}!',
  'Que este ano venha cheio de boas conversas, boas partidas e boa companhia.': 'ఈ సంవత్సరం మంచి మాటలు, మంచి ఆటలు, మంచి తోడుతో నిండిపోవాలి.',
  'Quem abre o site': 'సైట్ తెరిచేవారు',
  'Quem anda com você': 'మీతో ఉండేవారు',
  'Quem canta': 'పాడేవారు',
  'quem cuida do Syden': 'Sydenను చూసుకునేవారు',
  'Quem cuida do Syden vai olhar. Obrigado por avisar.': 'Sydenను చూసుకునేవారు పరిశీలిస్తారు. తెలియజేసినందుకు ధన్యవాదాలు.',
  'Quem está aqui não vê as suas mensagens nem você as dele, não consegue abrir conversa privada com você e não pode te mandar pedido de amizade.': 'ఇక్కడ ఉన్నవారికి మీ సందేశాలు కనిపించవు, మీకు వారివి కనిపించవు; వారు మీతో ప్రైవేట్ సంభాషణ మొదలుపెట్టలేరు, స్నేహ అభ్యర్థన పంపలేరు.',
  'Quem estiver na sala será desconectado. Dá para trazer a sala de volta por {dias} dias, em Configurações → Comunidade → Lixeira.': 'గదిలో ఉన్నవారందరూ బయటికి వస్తారు. {dias} రోజుల వరకు సెట్టింగ్‌లు → కమ్యూనిటీ → చెత్తబుట్ట నుంచి గదిని తిరిగి తేవచ్చు.',
  'Quem falou': 'ఎవరు మాట్లాడారు',
  'Quem tiver este código entra na comunidade: pela tela de cadastro, se ainda não tem conta, ou pelo botão de entrar, se já usa o Syden.': 'ఈ కోడ్ ఉన్నవారు కమ్యూనిటీలోకి రాగలరు: ఖాతా లేకపోతే నమోదు తెర నుంచి, ఇప్పటికే Syden వాడుతుంటే లాగిన్ బటన్ నుంచి.',
  'Quente, mas sem gritar.': 'వెచ్చగా, కానీ కేకలు వేయకుండా.',
