  'Sair de {comunidade}? As suas mensagens continuam lá para quem ficou.': '{comunidade} నుంచి వెళ్ళిపోవాలా? మిగిలినవారి కోసం మీ సందేశాలు అక్కడే ఉంటాయి.',
