  'Saúde do servidor': 'సర్వర్ ఆరోగ్యం',
  'Se existir uma conta com esse endereço, o link para escolher uma senha nova chegou lá. Ele vale por 1 hora.': 'ఆ చిరునామాతో ఖాతా ఉంటే, కొత్త పాస్‌వర్డ్ ఎంచుకునే లింక్ అక్కడికి చేరింది. అది 1 గంట చెల్లుబాటులో ఉంటుంది.',
  'Selo da comunidade': 'కమ్యూనిటీ ట్యాగ్',
  'Selo que você veste': 'మీరు ధరించిన ట్యాగ్',
