  'Sem imagem, a comunidade aparece com as iniciais do nome.': 'చిత్రం లేకపోతే కమ్యూనిటీ పేరులోని మొదటి అక్షరాలతో కనిపిస్తుంది.',
  'Sem moldura': 'ఫ్రేమ్ లేకుండా',
