  'Testando… os números aparecem em instantes.': 'పరీక్షిస్తోంది… సంఖ్యలు కొద్ది క్షణాల్లో కనిపిస్తాయి.',
  'Testar a transmissão': 'స్క్రీన్ షేర్‌ను పరీక్షించు',
  'Testar microfone': 'మైక్‌ను పరీక్షించు',
