  'Tirar da mensagem': 'సందేశం నుంచి తీసేయి',
  'Tirar o selo': 'ట్యాగ్‌ను తీసేయి',
  'Tirar opção': 'ఎంపికను తీసేయి',
  'Título': 'శీర్షిక',
  'Toca um som quando alguém entra ou sai da sua sala, quando alguém começa a compartilhar a tela e quando você silencia ou ensurdece.': 'మీ గదిలోకి ఎవరైనా వచ్చినప్పుడు లేదా వెళ్ళినప్పుడు, ఎవరైనా స్క్రీన్ షేర్ మొదలుపెట్టినప్పుడు, మీరు మైక్ లేదా శబ్దాన్ని ఆపినప్పుడు ఒక శబ్దం వినిపిస్తుంది.',
  'Tocando…': 'వినిపిస్తోంది…',
  'Todas as cores girando devagar. A mais chamativa de todas.': 'అన్ని రంగులూ నెమ్మదిగా తిరుగుతూ. అన్నిటిలోకీ ఎక్కువ కంటపడేది.',
  'Todo mundo desta comunidade pode usar estes emojis escrevendo {exemplo} ou pelo botão de emoji do chat. Sem assinatura: está tudo liberado.': 'ఈ కమ్యూనిటీలోని అందరూ {exemplo} అని రాసి, లేదా చాట్‌లోని ఎమోజీ బటన్ ద్వారా ఈ ఎమోజీలను వాడవచ్చు. చందా అవసరం లేదు: అన్నీ అందుబాటులో ఉన్నాయి.',
  'Tom mais alto e mais claro.': 'ఎత్తైన, స్పష్టమైన స్వరం.',
  'Tom mais baixo e mais encorpado.': 'లోతైన, దట్టమైన స్వరం.',
  'Tráfego de saída este mês': 'ఈ నెల బయటికి వెళ్ళిన డేటా',
  'Tráfego usado da franquia': 'పరిమితిలో వాడిన భాగం',
  'Transmissões dos outros': 'ఇతరుల స్క్రీన్ షేర్‌లు',
  'Traz de volta os emojis que vêm com o Syden. O que vocês enviaram continua como está, e nada vira cópia repetida.': 'Sydenతో వచ్చే ఎమోజీలను తిరిగి తెస్తుంది. మీరంతా పంపినవి అలాగే ఉంటాయి, ఏదీ రెట్టింపు కాదు.',
  'Trazendo…': 'తెస్తోంది…',
