  'Trocar senha': 'పాస్‌వర్డ్‌ను మార్చు',
  'Tudo aqui é de graça. Escolha o que quiser, troque quando quiser.': 'ఇక్కడ అన్నీ ఉచితం. కావలసినది ఎంచుకోండి, ఎప్పుడైనా మార్చుకోండి.',
