  'Você ainda não está em nenhuma comunidade': 'మీరు ఇంకా ఏ కమ్యూనిటీలోనూ లేరు',
  'Você ainda não tem amigos no Syden. A aba': 'Sydenలో మీకు ఇంకా స్నేహితులు లేరు. ఈ ట్యాబ్',
  'Você ainda não tem este item': 'ఈ వస్తువు ఇంకా మీ దగ్గర లేదు',
  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.': 'మీ దగ్గర ఇంకా ఒక్కటీ లేదు. ఇవి బహుమతిగా లేదా ప్రతిఫలంగా వస్తాయి — ఉదాహరణకు, మీ ఆలోచన Sydenలో చేరినప్పుడు.',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.': 'మీరు బయటి సేవ ద్వారా లాగిన్ అయ్యారు, ఈ ఖాతాకు ఇంకా పాస్‌వర్డ్ లేదు. ఇక్కడ ఒకటి పెట్టండి: అది రెండో లాగిన్ మార్గం అవుతుంది, తర్వాత ఆ సేవను ఆపేయడానికి వీలు కల్పించేది అదే.',
  'Você está silenciado!': 'మిమ్మల్ని మ్యూట్ చేశారు!',
  'Você foi convidado. É só escolher um nome, um e-mail e uma senha.': 'మిమ్మల్ని ఆహ్వానించారు. ఒక పేరు, ఒక ఇమెయిల్, ఒక పాస్‌వర్డ్ ఎంచుకుంటే చాలు.',
  'Você não bloqueou ninguém.': 'మీరు ఎవరినీ నిరోధించలేదు.',
  'Você não enviou nenhum pedido.': 'మీరు ఏ అభ్యర్థనా పంపలేదు.',
  'Você perde o acesso aos canais desta comunidade. Para voltar, vai precisar de um convite novo.': 'ఈ కమ్యూనిటీ ఛానెల్‌లకు మీ ప్రవేశం పోతుంది. తిరిగి రావాలంటే కొత్త ఆహ్వానం కావాలి.',
