  'A senha atual está incorreta.': 'ప్రస్తుత పాస్‌వర్డ్ తప్పు.',
  'A senha precisa ter pelo menos 6 caracteres.': 'పాస్‌వర్డ్‌కు కనీసం 6 అక్షరాలు కావాలి.',
  'A nova senha precisa ter pelo menos 6 caracteres.': 'కొత్త పాస్‌వర్డ్‌కు కనీసం 6 అక్షరాలు కావాలి.',
  'Esse nome de usuário já está em uso.': 'ఆ వినియోగదారు పేరు ఇప్పటికే వాడుకలో ఉంది.',
  'Escreva um e-mail válido: é por ele que você confirma a conta.': 'చెల్లుబాటు అయ్యే ఇమెయిల్ రాయండి: ఖాతాను దీనితోనే నిర్ధారిస్తారు.',
  'Falta confirmar o seu e-mail. Abra o link que enviamos para entrar.': 'మీ ఇమెయిల్ ఇంకా నిర్ధారించలేదు. లోపలికి రావడానికి మేము పంపిన లింక్ తెరవండి.',
