  'A letra e o efeito valem para o nome da comunidade, no alto da lista de canais.': 'అక్షరశైలి, ప్రభావం ఛానెల్ జాబితా పైన ఉన్న సముదాయ పేరుకు వర్తిస్తాయి.',
  'Tamanho do texto': 'అక్షరాల పరిమాణం',
