  'Uma regra ou aviso por linha: o coelho de quem chega lê um por um.': 'ఒక్కో వరుసకు ఒక నియమం లేదా సూచన: కొత్తగా వచ్చినవారి కుందేలు వాటిని ఒక్కొక్కటిగా చదువుతుంది.',
