  'Volume do soundboard': 'సౌండ్‌బోర్డ్ శబ్ద స్థాయి',
  'Procurar som': 'శబ్దం వెతుకు',
  'Nenhum som ainda. Adicione um abaixo, ou instale um pacote em Configurações → Soundboard.': 'ఇంకా శబ్దాలు లేవు. కింద ఒకటి చేర్చండి, లేదా సెట్టింగ్‌లు → సౌండ్‌బోర్డ్‌లో ఒక ప్యాక్‌ను పెట్టుకోండి.',
  'está transmitindo {oque}': '{oque} ప్రసారం చేస్తున్నారు',
  'está transmitindo': 'ప్రసారం చేస్తున్నారు',
  'Clique para ativar o áudio': 'ఆడియోను ఆన్ చేయడానికి క్లిక్ చేయండి',
