  'Ver as {n} transmissões lado a lado': '{n} స్క్రీన్ షేర్‌లను పక్కపక్కనే చూడు',
  'Todos do mesmo tamanho': 'అన్నీ ఒకే పరిమాణంలో',
  'Tela inteira': 'పూర్తి స్క్రీన్',
  'Tudo o que está na tela. O som do computador vai junto, já sem as vozes desta chamada.': 'తెరపై ఉన్నదంతా. కంప్యూటర్ శబ్దం కూడా వెళ్తుంది, ఈ కాల్‌లోని గొంతులు లేకుండా.',
  'Tudo o que está na tela. Para ir com som, marque "compartilhar áudio do sistema" na janelinha do navegador.': 'తెరపై ఉన్నదంతా. శబ్దంతో పంపడానికి, బ్రౌజర్ చిన్న కిటికీలో “సిస్టమ్ ఆడియోను షేర్ చేయి” గుర్తు పెట్టండి.',
  'Uma janela ou app': 'ఒక కిటికీ లేదా యాప్',
  'Só aquele programa, e o som do computador vai junto mesmo assim.': 'ఆ ప్రోగ్రామ్ మాత్రమే, అయినా కంప్యూటర్ శబ్దం కూడా వెళ్తుంది.',
  'Opções da transmissão': 'స్క్రీన్ షేర్ ఎంపికలు',
  'Compartilhar tela': 'స్క్రీన్ షేర్ చేయి',
  'Trocar para…': 'దీనికి మారు…',
  'O que compartilhar?': 'ఏం షేర్ చేయాలి?',
  'O som do computador vai junto sozinho.': 'కంప్యూటర్ శబ్దం దానంతట అదే వెళ్తుంది.',
  'No navegador, o som só vai se você marcar a caixinha de áudio na janelinha que abrir. No app do Syden ele vai sozinho.': 'బ్రౌజర్‌లో, తెరుచుకునే చిన్న కిటికీలో ఆడియో పెట్టెను మీరు గుర్తు పెడితేనే శబ్దం వెళ్తుంది. Syden యాప్‌లో అది దానంతట అదే వెళ్తుంది.',
  'Parar de compartilhar': 'షేర్ చేయడం ఆపు',
  'Dá para mandar até {n} arquivos por mensagem.': 'ఒక సందేశంలో {n} ఫైళ్ళ వరకు పంపవచ్చు.',
