  'Ao lado de um objeto de tamanho conhecido aparece outro, e cada um aumenta ou diminui esse outro até achar o tamanho certo. Quem chegar mais perto ganha mais pontos.': 'తెలిసిన పరిమాణం ఉన్న వస్తువు పక్కన మరొకటి కనిపిస్తుంది; ప్రతి ఒక్కరూ సరైన పరిమాణం అనుకునే వరకు దాన్ని పెద్దదిగా లేదా చిన్నదిగా చేస్తారు. అత్యంత దగ్గరగా వచ్చినవారికి ఎక్కువ పాయింట్లు వస్తాయి.',
