  'Você não votou nesta.': 'దీనికి నువ్వు ఓటు వేయలేదు.',
  'Só aquele programa, sem som: o navegador não pega o som de uma janela. Para ir com som, use a tela inteira.': 'ఆ ప్రోగ్రామ్ మాత్రమే, శబ్దం లేకుండా: బ్రౌజర్ విండో శబ్దాన్ని పట్టుకోదు. శబ్దంతో పంపాలంటే పూర్తి స్క్రీన్‌ని ఉపయోగించు.',
  'Na sala de voz, com a turma': 'వాయిస్ గదిలో, స్నేహితులతో',
  'Esperando alguém da sala sentar do outro lado…': 'గదిలో ఎవరైనా ఎదురుగా కూర్చోవడం కోసం ఎదురుచూస్తున్నాం…',
  '{nome} quer jogar. Sente do outro lado!': '{nome} ఆడాలనుకుంటున్నారు. ఎదురుగా కూర్చో!',
