  '{nome} demorou demais para jogar. {vencedor} venceu!': '{nome} ఆడటానికి చాలా సమయం తీసుకున్నారు. {vencedor} గెలిచారు!',
  '{nome} desistiu. {vencedor} venceu!': '{nome} తప్పుకున్నారు. {vencedor} గెలిచారు!',
