  '{nome} apertou STOP!': '{nome} STOP నొక్కారు!',
  'Clique numa resposta que não vale. Ela cai se mais da metade concordar.': 'చెల్లని జవాబుపై క్లిక్ చేయి. సగం కంటే ఎక్కువ మంది అంగీకరిస్తే అది తొలగిపోతుంది.',
  'Pontos da rodada': 'రౌండ్ పాయింట్లు',
