  'Cobra': 'పాము',
  'Tartaruga': 'తాబేలు',
  'Sapo': 'కప్ప',
  'Borboleta': 'సీతాకోకచిలుక',
  'Aranha': 'సాలీడు',
  'Caracol': 'నత్త',
  'Polvo': 'ఆక్టోపస్',
  'Tubarão': 'సొరచేప',
  'Baleia': 'తిమింగలం',
  'Golfinho': 'డాల్ఫిన్',
  'Pinguim': 'పెంగ్విన్',
