  'Só quem desenha mexe no desenho.': 'గీసేవాళ్లు మాత్రమే బొమ్మను మార్చగలరు.',
  'Cargos automáticos': 'ఆటోమేటిక్ పాత్రలు',
  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': 'ముందుగా కమ్యూనిటీ పాత్రలను సభ్యులు విభాగంలో సృష్టించండి. ఆ తర్వాత అవి వాటంతట అవే ఇవ్వబడేలా ఇక్కడికి తిరిగి రండి.',
  'Cargo de quem entra': 'చేరేవారి పాత్రలు',
  'Toda pessoa nova recebe estes cargos ao entrar na comunidade.': 'కమ్యూనిటీలో చేరే ప్రతి కొత్త వ్యక్తికి ఈ పాత్రలు లభిస్తాయి.',
  'Cargos por reação': 'ప్రతిస్పందన ద్వారా పాత్రలు',
  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'Syden ఛానెల్‌లో ప్రతి పాత్రకు ఒక ఎమోజీతో ఒక సందేశాన్ని ప్రచురిస్తుంది. ప్రతిస్పందించినవారికి పాత్ర లభిస్తుంది; ప్రతిస్పందనను తీసేసినవారు దాన్ని కోల్పోతారు.',
  'Apagar o painel': 'ప్యానెల్‌ను తొలగించు',
  'Escolha os seus cargos reagindo aqui embaixo!': 'కింద ప్రతిస్పందించి మీ పాత్రలను ఎంచుకోండి!',
  'Texto do painel': 'ప్యానెల్ వచనం',
  'Emoji {n}': 'ఎమోజీ {n}',
  'Cargo {n}': 'పాత్ర {n}',
  'Mais um emoji': 'మరో ఎమోజీ',
  'Publicar o painel': 'ప్యానెల్‌ను ప్రచురించు',
  'Quais jogos a turma joga, com quantas pessoas e quantas partidas vão até o fim. Só contagem: respostas e desenhos não são guardados. Conta a partir de 12/10/2026.': 'బృందం ఏ ఆటలు ఆడుతుంది, ఎంత మందితో, ఎన్ని మ్యాచ్‌లు చివరి వరకు సాగుతాయి. లెక్క మాత్రమే: సమాధానాలు, బొమ్మలు భద్రపరచబడవు. 12/10/2026 నుండి లెక్కించబడుతుంది.',
  '{n} dias': '{n} రోజులు',
  'Partidas': 'మ్యాచ్‌లు',
