  'Até o fim': 'చివరి వరకు',
  'Por partida': 'ఒక్కో మ్యాచ్‌కు',
  'Duração': 'వ్యవధి',
  'última em {data}': 'చివరిది: {data}',
  'O som': 'శబ్దం',
  'A música': 'పాట',
  'O emoji': 'ఎమోజీ',
  'O arquivo': 'ఫైల్',
  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) Syden నుండి తీసివేయబడింది, ఎందుకంటే దానిపై హక్కులు తమవని {quem} చెబుతున్నారు. ప్రచురించడానికి మీకు అనుమతి ఉండి ఉంటే, ఇక్కడ జవాబిచ్చి వివరించండి: మీ జవాబు పరిగణనలోకి తీసుకోబడుతుంది. ఇది స్పష్టమయ్యే వరకు, అది తీసివేసే ఉంటుంది. ఇది ఎలా పనిచేస్తుందో నిబంధనల 4వ విభాగం వివరిస్తుంది: https://syden.chat/termos.html#direito-autoral',
  '«{nome}» saiu.': '«{nome}» తీసివేయబడింది.',
  'Saíram junto {n} cópia(s) do mesmo arquivo.': 'అదే ఫైల్ యొక్క తీసివేసిన కాపీలు: {n}.',
  'Quem subiu recebeu o aviso numa conversa com você.': 'అప్‌లోడ్ చేసినవారికి మీతో సంభాషణలో నోటీసు వెళ్లింది.',
  'Não havia a quem avisar.': 'తెలియజేయడానికి ఎవరూ లేరు.',
  'É a retirada número {n} desta pessoa.': 'ఇది ఈ వ్యక్తి యొక్క {n}వ తీసివేత.',
  'Direito autoral': 'కాపీరైట్',
  'Quem tem o direito escreve para direitos@syden.chat dizendo o que é e onde está. Procure pelo nome, retire, e quem subiu recebe o aviso numa conversa com você, onde pode contestar.': 'హక్కులు ఉన్నవారు direitos@syden.chat కు అది ఏమిటో, ఎక్కడ ఉందో రాస్తారు. పేరుతో వెతకండి, తీసివేయండి; అప్‌లోడ్ చేసినవారికి మీతో సంభాషణలో నోటీసు వెళ్తుంది, అక్కడ వారు అభ్యంతరం తెలపవచ్చు.',
  'Nome do som, da música, do emoji ou do arquivo': 'శబ్దం, పాట, ఎమోజీ లేదా ఫైల్ పేరు',
  'Procurar conteúdo': 'కంటెంట్‌ను వెతుకు',
  'Procurar': 'వెతుకు',
  'Nada com esse nome.': 'ఆ పేరుతో ఏదీ లేదు.',
