  'Uma comunidade é um lugar com canais de texto e salas de voz, como um servidor do Discord. Entre na de um amigo com o código de convite dele, ou crie a sua.': 'కమ్యూనిటీ అంటే టెక్స్ట్ ఛానెల్‌లు, వాయిస్ గదులు ఉండే చోటు, Discord సర్వర్ లాగా. స్నేహితుడి ఆహ్వాన కోడ్‌తో వారి కమ్యూనిటీలో చేరండి, లేదా మీదే సృష్టించండి.',
  'Ligue a sua conta do Google, Discord, GitHub ou Steam para entrar no Syden por lá, sem digitar senha. Dá para ligar mais de um, e todos levam a esta mesma conta.': 'పాస్‌వర్డ్ టైప్ చేయకుండా అక్కడి నుంచే Sydenలోకి రావడానికి మీ Google, Discord, GitHub లేదా Steam ఖాతాను కలపండి. ఒకటి కంటే ఎక్కువ కలపవచ్చు, అన్నీ ఇదే ఖాతాకు తీసుకొస్తాయి.',
