  'Data de nascimento': 'పుట్టిన తేదీ',
  'Decidido por uma pessoa da equipe do Syden em {quando}.': '{quando}న Syden బృందంలోని ఒకరు తీసుకున్న నిర్ణయం.',
  'Declaro que sou o pai, a mãe ou o responsável legal por esta pessoa.': 'నేను ఈ వ్యక్తి యొక్క తండ్రి, తల్లి లేదా చట్టపరమైన సంరక్షకులని ప్రకటిస్తున్నాను.',
  'Denunciar a transmissão de {nome}': '{nome} స్క్రీన్ షేర్‌పై ఫిర్యాదు చేయి',
  'Denunciar esta transmissão': 'ఈ స్క్రీన్ షేర్‌పై ఫిర్యాదు చేయి',
  'Denunciar mensagem': 'సందేశంపై ఫిర్యాదు చేయి',
  'Depois de informada, ela não muda por aqui: confira antes de continuar.': 'ఇచ్చిన తర్వాత ఇక్కడి నుంచి మారదు: కొనసాగే ముందు సరిచూసుకోండి.',
  'Desfazer o banimento': 'నిషేధాన్ని ఎత్తివేయి',
  'Desligar a conta de {nome}? De 13 a 15 anos, ela fica parada até ser ligada de novo.': '{nome} ఖాతాను విడదీయాలా? 13 నుంచి 15 ఏళ్ల వయసులో, మళ్లీ లింక్ చేసే వరకు అది నిలిచిపోతుంది.',
  'Desligar esta conta': 'ఈ ఖాతాను విడదీయి',
  'Ele entra no Syden com a conta dele (ou cria uma) e abre Configurações → Família.': 'వారు తమ ఖాతాతో Syden లోకి వచ్చి (లేదా కొత్తది సృష్టించి) సెట్టింగ్‌లు → కుటుంబం తెరుస్తారు.',
  'Enviar esta imagem junto (só quem cuida do Syden vê)': 'ఈ చిత్రాన్ని కూడా పంపు (Syden ని చూసుకునేవారు మాత్రమే చూస్తారు)',
