  'Você não pode ser o seu próprio responsável.': 'మీకు మీరే సంరక్షకులుగా ఉండలేరు.',
  'Você pode ligar a sua conta a um pai, mãe ou responsável, se quiser.': 'మీకు కావాలంటే, మీ ఖాతాను తండ్రి, తల్లి లేదా సంరక్షకులతో లింక్ చేయవచ్చు.',
  // A proteção de crianças e adolescentes, a denúncia de transmissão e o banimento (17/10/2026)
  'Ferramentas': 'సాధనాలు',
  // A proteção de crianças e adolescentes, a denúncia de transmissão e o banimento (17/10/2026)
  'Pôster do café': 'కాఫీ పోస్టర్',
  // O cartão das peças do quarto e do salão (17/10/2026)
  'Macio e baixinho, fácil de puxar para perto da conversa.': 'మెత్తగా, పొట్టిగా, సంభాషణ దగ్గరికి లాగడం సులభం.',
  'Funda e confortável, boa para ler ou ver alguém jogar.': 'లోతుగా, సౌకర్యంగా, చదవడానికి లేదా ఎవరైనా ఆడుతుంటే చూడడానికి బాగుంటుంది.',
  'É aqui que o coelho dorme quando você está ausente.': 'మీరు లేనప్పుడు కుందేలు నిద్రపోయేది ఇక్కడే.',
  'Com o abajur em cima, que acende o quarto à noite.': 'పైన దీపంతో, రాత్రి గదిని వెలిగిస్తుంది.',
  'Onde moram as roupas e os enfeites do coelho.': 'కుందేలు బట్టలు, అలంకరణలు ఉండే చోటు.',
  'São seis cores: escolha a dele no Editar.': 'ఆరు రంగులు ఉన్నాయి: సవరించు మోడ్‌లో ఒకటి ఎంచుకోండి.',
  'O coelho senta aqui quando você entra numa call.': 'మీరు callలో చేరినప్పుడు కుందేలు ఇక్కడ కూర్చుంటుంది.',
  'Folhas grandes para encher um canto de verde.': 'ఒక మూలను పచ్చదనంతో నింపే పెద్ద ఆకులు.',
  'Pequena e cheia, num cesto de palha.': 'చిన్నగా, దట్టంగా, గడ్డి బుట్టలో.',
  'Mostra quem está transmitindo agora.': 'ఇప్పుడు ఎవరు ప్రసారం చేస్తున్నారో చూపిస్తుంది.',
  'Cabe a turma inteira na frente da TV.': 'టీవీ ముందు బృందం మొత్తం పడుతుంది.',
  'Baixinha, perto do sofá, para a pipoca e o refrigerante.': 'పొట్టిగా, సోఫా దగ్గర, పాప్‌కార్న్, కూల్ డ్రింక్ కోసం.',
  'Abre os mini-games para jogar com a turma.': 'బృందంతో ఆడడానికి చిన్న ఆటలను తెరుస్తుంది.',
  'Cada prateleira guarda os canais da comunidade.': 'ప్రతి అరలో కమ్యూనిటీ ఛానెళ్లు ఉంటాయి.',
  'Onde o coelho do recado espera quem chega.': 'సందేశం కుందేలు వచ్చేవాళ్ల కోసం ఎదురుచూసే చోటు.',
  'Alta, para sentar no balcão e conversar.': 'ఎత్తుగా, కౌంటర్ దగ్గర కూర్చుని మాట్లాడడానికి.',
  'Uma máquina de música antiga, com luzes que acendem à noite.': 'రాత్రి వెలిగే దీపాలతో ఒక పాత సంగీత యంత్రం.',
  'Com caixa de som, pronto para o karaokê.': 'స్పీకర్‌తో, కరోకేకి సిద్ధం.',
  'Redonda, para cartas, tabuleiro e conversa.': 'గుండ్రంగా, పేకాట, బోర్డ్ ఆటలు, కబుర్ల కోసం.',
  'De madeira, com o assento estofado.': 'చెక్కతో, మెత్తని సీటుతో.',
  'Suco, refrigerante e água sempre gelados.': 'జ్యూస్, కూల్ డ్రింక్, నీళ్లు ఎప్పుడూ చల్లగా.',
  'A cozinha da turma. O botão direito acende e apaga o fogão.': 'బృందం వంటగది. కుడి బటన్ పొయ్యిని వెలిగిస్తుంది, ఆపుతుంది.',
  'Um pufe enorme, para afundar e ficar.': 'మునిగిపోయి ఉండిపోవడానికి ఒక పెద్ద పఫ్.',
  'Pendurado no gancho, esperando a próxima call.': 'కొక్కేనికి వేలాడుతూ, తర్వాతి call కోసం ఎదురుచూస్తోంది.',
  'Fotos dos amigos presas num varal.': 'తాడుకు వేలాడే స్నేహితుల ఫోటోలు.',
  'Recados e ideias presos com alfinete.': 'గుండుసూదులతో గుచ్చిన సందేశాలు, ఆలోచనలు.',
  'Livros, uma plantinha e um vaso.': 'పుస్తకాలు, ఒక చిన్న మొక్క, ఒక కుండీ.',
  'Um pôr do sol sobre os campos.': 'పొలాలపై సూర్యాస్తమయం.',
  'Xícaras, potes e garrafas de suco.': 'కప్పులు, జాడీలు, జ్యూస్ సీసాలు.',
  'Potes de biscoito e pipoca para dividir.': 'పంచుకోవడానికి బిస్కెట్లు, పాప్‌కార్న్ జాడీలు.',
  'As taças das vitórias da turma.': 'బృందం గెలుపుల కప్పులు.',
  'Um coelho de neon que brilha no escuro.': 'చీకట్లో మెరిసే నియాన్ కుందేలు.',
  'Um relógio de madeira para ninguém perder a hora.': 'ఎవరూ సమయం మరిచిపోకుండా ఒక చెక్క గడియారం.',
  'Para quem quiser puxar uma música.': 'ఒక పాట వాయించాలనుకునే ఎవరికైనా.',
  'Dá no banheiro. Bata antes de entrar.': 'బాత్‌రూమ్‌కి వెళ్తుంది. లోపలికి వెళ్లే ముందు తట్టండి.',
  'O cartaz do karaokê, em três versões: palco, neon e fogo.': 'కరోకే పోస్టర్, మూడు రకాలుగా: వేదిక, నియాన్, మంట.',
  'Dois coelhos, um café e a fofoca do dia.': 'రెండు కుందేళ్లు, ఒక కాఫీ, ఆ రోజు ముచ్చట్లు.',
  'Café quentinho, ainda soltando fumaça.': 'ఇంకా ఆవిరి వస్తున్న వేడి కాఫీ.',
  'Suco de laranja com canudinho.': 'స్ట్రాతో ఆరెంజ్ జ్యూస్.',
  'Uma lata gelada.': 'చల్లని కూల్ డ్రింక్ డబ్బా.',
  'Uma suculenta pequena, que quase não pede água.': 'దాదాపు నీళ్లు అక్కర్లేని ఒక చిన్న సక్యులెంట్.',
  'Uma pilha de livros para ler depois.': 'తర్వాత చదవడానికి పుస్తకాల గుట్ట.',
  'O console da turma, com o controle ao lado.': 'బృందం కన్సోల్, పక్కనే కంట్రోలర్.',
  'Um balde de pipoca para ver a transmissão.': 'ప్రసారం చూడడానికి పాప్‌కార్న్ బకెట్.',
  'Uma lembrança num porta-retrato.': 'ఫోటో ఫ్రేమ్‌లో ఒక జ్ఞాపకం.',
  'Uma pizza inteira para dividir.': 'పంచుకోవడానికి ఒక పూర్తి పిజ్జా.',
