  'Se todos na chamada virem o mesmo código, ninguém está no meio da conversa.': 'కాల్‌లో ఉన్న అందరికీ ఒకే కోడ్ కనిపిస్తే, సంభాషణ మధ్యలో ఎవరూ లేరు.',
