  'Era: {nome}': 'జవాబు: {nome}',
  'Escreva o começo do nome e escolha da lista.': 'పేరు మొదలు రాసి, జాబితా నుండి ఎంచుకోండి.',
  'Seu chute': 'మీ అంచనా',
  'Chutes: {n}': 'అంచనాలు: {n}',
  'Monstros de fantasia': 'కాల్పనిక రాక్షసులు',
  'Sai um monstro secreto, e cada um chuta outros da lista. Cada chute mostra o que bate com o secreto: tipo, tamanho, nível, alinhamento e como ele se desloca. Quem acertar com menos chutes ganha mais pontos.': 'ఒక రహస్య రాక్షసం ఎంపికవుతుంది, ప్రతి ఒక్కరూ జాబితా నుండి వేరేవాటిని ఊహిస్తారు. ప్రతి అంచనా రహస్యమైనదానితో ఏది సరిపోతుందో చూపిస్తుంది: రకం, పరిమాణం, స్థాయి, ధోరణి, కదిలే విధానం. తక్కువ అంచనాలతో సరిగ్గా కనిపెట్టినవారికి ఎక్కువ పాయింట్లు.',
  'Sai uma figura secreta da mitologia, e cada um chuta outras. Cada chute mostra o que bate com a secreta: a mitologia, o tipo, a forma e o que ela governa. Quem acertar com menos chutes ganha mais pontos.': 'పురాణాల నుండి ఒక రహస్య పాత్ర ఎంపికవుతుంది, ప్రతి ఒక్కరూ వేరే పాత్రలను ఊహిస్తారు. ప్రతి అంచనా రహస్య పాత్రతో ఏది సరిపోతుందో చూపిస్తుంది: పురాణం, రకం, ఆకారం, అది పాలించే రంగం. తక్కువ అంచనాలతో సరిగ్గా కనిపెట్టినవారికి ఎక్కువ పాయింట్లు.',
  'Países': 'దేశాలు',
  'Sai um país secreto, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a sub-região e a população. Quem acertar com menos chutes ganha mais pontos.': 'ఒక రహస్య దేశం ఎంపికవుతుంది, ప్రతి ఒక్కరూ వేరే దేశాలను ఊహిస్తారు. ప్రతి అంచనా రహస్య దేశానికి దూరం, దిశ, ప్రాంతం, ఉపప్రాంతం, జనాభాను చూపిస్తుంది. తక్కువ అంచనాలతో సరిగ్గా కనిపెట్టినవారికి ఎక్కువ పాయింట్లు.',
  'Apagar conversa': 'సంభాషణను తొలగించు',
  'A conversa sai da sua lista e as mensagens somem só para você. As outras pessoas continuam vendo tudo, e uma mensagem nova traz a conversa de volta.': 'సంభాషణ నీ జాబితా నుండి వెళ్లిపోతుంది, సందేశాలు నీకు మాత్రమే కనిపించవు. మిగతావాళ్లకు అన్నీ కనిపిస్తూనే ఉంటాయి, కొత్త సందేశం వస్తే సంభాషణ మళ్లీ వస్తుంది.',
