  'Quantos adversários do computador?': 'కంప్యూటర్ ప్రత్యర్థులు ఎంతమంది?',
  'Balões': 'బెలూన్లు',
  'Pegue as caixas e estoure os balões dos outros. Quem fica sem balão sai.': 'పెట్టెలు తీసుకుని ఇతరుల బెలూన్లు పగలగొట్టు. బెలూన్లు అయిపోయినవారు బయటకు.',
  'Você venceu!': 'గెలుపు!',
  '{posicao}º lugar, entre {total}': '{total} మందిలో {posicao}వ స్థానం',
  'Balões que sobraram: {n}': 'మిగిలిన బెలూన్లు: {n}',
  'Balões estourados: {n}': 'పగిలిన బెలూన్లు: {n}',
  'Freio de ar': 'గాలి బ్రేక్',
  'Turbo': 'టర్బో',
  'Pilotar': 'నడపడం',
  'Turbo (da segunda volta em diante)': 'టర్బో (రెండో ల్యాప్ నుంచి)',
  '{n} voltas': 'ల్యాప్‌లు: {n}',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'శక్తే ప్రాణం, టర్బో కూడా: అంచుకు తగిలితే ఖర్చవుతుంది, గులాబీ పట్టీ మళ్లీ నింపుతుంది.',
  'A nave explodiu: a energia acabou.': 'నౌక పేలిపోయింది: శక్తి అయిపోయింది.',
  'Posição: {posicao} de {total}': 'స్థానం: {total}లో {posicao}',
  'Escolher a pista': 'ట్రాక్ ఎంచుకో',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'వేలాడే ట్రాక్‌పై క్యారెట్ నౌకల పందెం, కార్ట్ కంటే చాలా వేగం. శక్తే ప్రాణం, టర్బో కూడా: అంచుకు తగిలితే ఖర్చవుతుంది, గులాబీ పట్టీ మళ్లీ నింపుతుంది, ట్రాక్ నుంచి బయటకు వెళ్తే పడిపోవడమే. ఒంటరిగా, గడియారానికి, స్నేహితుల దెయ్యాలకు ఎదురుగా.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'మూసిన మైదానంలో కార్ట్‌లు, ఒక్కోదానికి మూడు బెలూన్లు. పెట్టెలు తీసుకుని, వస్తువులతో ఇతరుల బెలూన్లు పగలగొట్టు: బెలూన్లు అయిపోయినవారు బయటకు, చివరి వరకు నిలిచినవారిదే గెలుపు.',
  'Esquadrilha da toca': 'బొరియ విమాన దళం',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'క్యారెట్ చిన్న విమానాలు తోట చీడలకు ఎదురుగా: విత్తనాలను తప్పించుకో, సహాయాలను అందుకో, చివర్లో యాంత్రిక దిష్టిబొమ్మను కూల్చు. బృందం అవే అలల్లో ఎగురుతుంది, దళం పాయింట్లు కలుస్తాయి.',
  'O espantalho caiu!': 'దిష్టిబొమ్మ కూలిపోయింది!',
  'A praga venceu desta vez.': 'ఈసారి చీడలు గెలిచాయి.',
