  'A sua Maravilha ficou de pé por 2 minutos.': 'నీ అద్భుతం 2 నిమిషాలు నిలిచింది.',
  'A Maravilha do computador ficou de pé por 2 minutos.': 'కంప్యూటర్ అద్భుతం 2 నిమిషాలు నిలిచింది.',
  'Você derrubou o centro da vila do computador.': 'నువ్వు కంప్యూటర్ గ్రామ కేంద్రాన్ని కూల్చావు.',
  'O computador derrubou o seu centro da vila.': 'కంప్యూటర్ నీ గ్రామ కేంద్రాన్ని కూల్చింది.',
