  'A sua Maravilha está pronta: defenda-a por 2 minutos!': 'నీ అద్భుతం సిద్ధం: దాన్ని 2 నిమిషాలు కాపాడు!',
  'O computador terminou uma Maravilha: derrube-a em 2 minutos!': 'కంప్యూటర్ ఒక అద్భుతాన్ని పూర్తి చేసింది: 2 నిమిషాల్లో దాన్ని కూల్చు!',
