  'Este jogo não se joga na sala.': 'ఈ ఆట గదిలో ఆడరు.',
  'Ponha os seus navios no mar.': 'నీ ఓడలను సముద్రంలో పెట్టు.',
  'Esperando {nome} pôr os navios…': '{nome} ఓడలు పెట్టేవరకు వేచి ఉంది…',
  'Os dois estão pondo os navios…': 'ఇద్దరూ ఓడలు పెడుతున్నారు…',
  'Navio de {n} casas': '{n} గడుల ఓడ',
  'Seus navios': 'నీ ఓడలు',
  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'ఒక ఓడను ఎంచుకుని సముద్రాన్ని తాకు. చోటు మార్చడానికి లాగు.',
  'Sortear a frota': 'యాదృచ్ఛిక నౌకాదళం',
  'Sua frota já está pronta.': 'నీ నౌకాదళం ఇప్పటికే సిద్ధం.',
  'Ponha todos os navios antes.': 'ముందు అన్ని ఓడలనూ పెట్టు.',
  'Escolha um navio.': 'ఒక ఓడను ఎంచుకో.',
  'O navio não cabe aí.': 'ఓడ అక్కడ పట్టదు.',
  'Os navios não podem encostar um no outro.': 'ఓడలు ఒకదానికొకటి తాకకూడదు.',
  'Minigolfe 3D': 'మినీగోల్ఫ్ 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': '3Dలో ఎనిమిది గుంతలు, ర్యాంపులు, కోట, గాలిమరతో, అందరూ ఒకే సమయంలో ఒకే గుంతను ఆడతారు. గురిపెట్టడానికి, బలం ఇవ్వడానికి లాగి, ఆపై వదులు. మొత్తంలో తక్కువ దెబ్బలు కొట్టినవారు గెలుస్తారు.',
  'Ver o buraco de cima': 'గుంతను పై నుంచి చూడు',
  'Fora da pista! Mais uma tacada.': 'దారి బయట! ఇంకో దెబ్బ.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'గురిపెట్టడానికి పక్కకు, బలానికి కిందికి లాగి, ఆపై వదులు. కీబోర్డ్‌లో: బాణాలు గురిపెడతాయి, నొక్కి పట్టిన స్పేస్ బలం ఇస్తుంది.',
  'Futebol dos coelhos': 'కుందేళ్ల ఫుట్‌బాల్',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'చిన్న మైదానంలో ఫుట్‌బాల్, పై నుంచి. బంతిని తీసుకెళ్లడానికి దాన్ని తాకు, బలంగా కొట్టడానికి స్పేస్ నొక్కి పట్టు, X తో పాస్ చెయ్యి. గదిలో జట్లు రోబోలతో నిండుతాయి.',
  'Quantos por time?': 'ఒక్కో జట్టుకు ఎంతమంది?',
  'Seu time venceu!': 'నీ జట్టు గెలిచింది!',
  'Seu time perdeu.': 'నీ జట్టు ఓడిపోయింది.',
