  'Chutar (segure para mais força)': 'షూట్ (ఎక్కువ బలానికి నొక్కి పట్టు)',
  'Gol!': 'గోల్!',
  'Gol contra': 'సొంత గోల్',
  'Partida inválida.': 'చెల్లని మ్యాచ్.',
  'Ninguém para jogar.': 'ఆడటానికి ఎవరూ లేరు.',
  'Caça às pragas da horta': 'తోటలో చీడల వేట',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'కాకులు, మిడతలు తోటపై దాడి చేస్తున్నాయి. అవి పారిపోకముందే గురిపెట్టి క్లిక్ చెయ్యి: తూటాలు లెక్కలో ఉంటాయి, ప్రతి అల ఇంకా వేగంగా వస్తుంది. అత్యధిక పాయింట్లు సాధించినవారు గెలుస్తారు.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'చీడలు పారిపోకముందే గురిపెట్టి క్లిక్ చెయ్యి. ప్రతి కాల్పుకు ఒక క్యారెట్ ఖర్చవుతుంది.',
