  'Até sobrar um': 'ఒక్కరు మిగిలే వరకు',
  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'బ్రెజిల్ రాజధానుల గుండా తిరుగు, నగరాలు కొను, వాటిపై ఆగినవారి నుంచి అద్దె వసూలు చెయ్యి. మొత్తం ప్రాంతం నీదైతే భవనాలు కట్టవచ్చు. మార్పిడి చేసుకో, వేలాల్లో పోటీ పడు, డబ్బు అయిపోకుండా చూసుకో.',
