  'A foto só aparece depois de salvar o recado.': 'సందేశం భద్రపరిచాకే ఫోటో కనిపిస్తుంది.',
  'Figurinhas': 'స్టిక్కర్లు',
  'Figurinha não encontrada.': 'స్టిక్కర్ కనిపించలేదు.',
  'A sua coleção de figurinhas está cheia. Tire alguma para pôr outra.': 'నీ స్టిక్కర్ల సేకరణ నిండిపోయింది. ఇంకొకటి పెట్టడానికి ఒకదాన్ని తీసేయి.',
  'Figurinha': 'స్టిక్కర్',
  'Salva nas suas figurinhas': 'నీ స్టిక్కర్లలో భద్రపరచబడింది',
  'Não deu para salvar': 'భద్రపరచలేకపోయాం',
  'Salvar figurinha': 'స్టిక్కర్ భద్రపరచు',
  'Essa imagem é grande demais para virar figurinha (até 1 MB).': 'ఈ చిత్రం స్టిక్కర్‌గా మారడానికి చాలా పెద్దది (1 MB వరకు).',
  'Use uma imagem PNG, JPG, GIF ou WEBP.': 'PNG, JPG, GIF లేదా WEBP చిత్రం వాడు.',
  'Arrumar': 'సర్దు',
  'Criar figurinha': 'స్టిక్కర్ సృష్టించు',
  'Tirar o fundo': 'నేపథ్యాన్ని తీసివేయి',
  'Contorno': 'అంచు గీత',
  'O fundo não é de uma cor só, e ficou como veio.': 'నేపథ్యం ఒకే రంగులో లేదు, కాబట్టి అలాగే ఉంచబడింది.',
  'No app do Syden, o recorte funciona com qualquer fundo.': 'Syden యాప్‌లో ఏ నేపథ్యాన్నైనా తీసివేయవచ్చు.',
  'O recorte com o modelo falhou, e ficou o recorte simples.': 'మోడల్‌తో తీసివేయడం విఫలమైంది, కాబట్టి సులభమైన పద్ధతి వాడబడింది.',
  'Mandar figurinha': 'స్టిక్కర్ పంపు',
  'Tirar figurinha': 'స్టిక్కర్ తీసేయి',
  'Crie figurinhas com as suas imagens, ou salve as que receber numa conversa.': 'నీ చిత్రాలతో స్టిక్కర్లు సృష్టించు, లేదా సంభాషణలో వచ్చినవాటిని భద్రపరచు.',
  'Dominó': 'డొమినో',
  'Truco': 'ట్రూకో',
  'Damas': 'చెక్కర్స్',
  'Batalha naval': 'యుద్ధనౌకల ఆట',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'మామూలు డొమినో, 2 నుంచి 4 మంది (4 మంది అయితే జంటలుగా). రాళ్లను చివరలకు జత చెయ్యి; అన్నీ ముందుగా దించినవారు మిగతావారి చేతుల్లోని పాయింట్లు గెలుస్తారు.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'బ్రెజిల్ ట్రూకో, తిప్పిన కార్డు, ట్రంప్ కార్డులతో, 2 మంది లేదా 4 మంది జంటలుగా. ట్రూకో అడుగు, ఆరు, తొమ్మిది, పన్నెండుకు పెంచు, లేదా పారిపో. 12 పాయింట్లు చేసినవారు గెలుస్తారు.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'బ్రెజిల్ చెక్కర్స్: తినడం తప్పనిసరి, ముందుకీ వెనక్కీ; రాణి మొత్తం వికర్ణం వెంబడి కదులుతుంది. గది చూస్తుంది.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'ప్రతి ఒక్కరూ తమ నౌకాదళాన్ని దాచి, ఎదుటివారి సముద్రంలో కాలుస్తారు. తగిలితే, మళ్లీ కాల్చవచ్చు. మొత్తం దళాన్ని ముందుగా ముంచినవారు గెలుస్తారు. గది చూస్తుంది.',
