  'Cozinha da toca': 'బొరియలోని వంటగది',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'పెట్టెల నుంచి పదార్థాలు తీసుకుని, బల్లపై తరిగి, మాడకుండా పొయ్యి మీద, ఓవెన్‌లో వండి, పళ్లెంలో అమర్చి కిటికీ వద్ద ఇవ్వండి. అందరికీ ఒకే ఆర్డర్లు వస్తాయి: 3 నిమిషాల్లో ఎక్కువ పళ్లేలు ఇచ్చినవారు గెలుస్తారు.',
  'Pegar ou largar': 'ఎత్తు లేదా పెట్టు',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'ఈ ఆటకు 3D గ్రాఫిక్స్ కావాలి, అవి ఈ పరికరంలో తెరుచుకోలేదు.',
  'Este prato não é o pedido.': 'ఈ పళ్లెం ఆర్డర్ కాదు.',
