  'Adicionar foto': "ఫోటో జోడించు",
  'Apagar este bolão, com os palpites?': "అంచనాలతో సహా ఈ పోటీని తొలగించాలా?",
  'Fecha em {quando}': "ముగిసేది: {quando}",
