  'Ganha quem chegar mais perto. Só pontos, sem dinheiro.': "అత్యంత దగ్గరి అంచనా గెలుస్తుంది. పాయింట్లు మాత్రమే, డబ్బు లేదు.",
  'Lançar resposta': "జవాబు నమోదు చేయి",
