  'Reabrir palpites': "అంచనాలు మళ్లీ తెరువు",
  'Resposta certa': "సరైన జవాబు",
  'Resposta: {quando}': "జవాబు: {quando}",
  'Seu palpite': "నీ అంచనా",
  'Seu palpite está salvo. Dá para mudar até fechar.': "నీ అంచనా సేవ్ అయింది. మూసే వరకు మార్చవచ్చు.",
  // O fundo da câmera (16/11/2026)
  'Fundo da câmera': "కెమెరా నేపథ్యం",
  'Desfocado': "మసకబార్చు",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "నీ వెనుక కనిపించేదాన్ని మసకబారుస్తుంది, తుడిచేస్తుంది లేదా మారుస్తుంది. దీని కోసం కెమెరా చిత్రం నీ కంప్యూటర్ నుంచి బయటకు వెళ్లదు.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "స్వతహా",
  'Resolução': "రిజల్యూషన్",
  'Quadros por segundo': "సెకనుకు ఫ్రేమ్‌లు",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "ఆటోమేటిక్ ఎంపిక తప్పినప్పుడు: ప్రసారం మొదలు నుంచి చివరి వరకు రిజల్యూషన్, ఫ్రేమ్‌లు నువ్వు ఎంచుకున్నట్టే ఉంటాయి.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "నీ కంప్యూటర్‌లోనే జరిగే గొంతు, కెమెరా ఎఫెక్ట్‌లు, ఏ సర్వర్‌కూ ఏమీ పంపకుండా.",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "బొరియ చెరసాల",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "పుట్టగొడుగు రాజు బొరియను కలిసి దాటండి: జీవులతో నిండిన గదులు, వెళ్లి తిరిగి వచ్చే క్యారెట్ ఉన్న పెట్టె, ఒకేసారి ఇద్దరు కావాల్సిన బటన్లు, తాళం వేసిన తలుపు. 1 నుండి 4 మంది.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "బొరియ రింగ్",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "కంప్యూటర్ ముగ్గురు ప్రత్యర్థులతో రిఫ్లెక్స్ బాక్సింగ్. ప్రతి పంచ్ సూచనను చదువు, తప్పించుకో లేదా అడ్డుకో, ఖాళీలో కొట్టు. గ్లవ్ మెరిసినప్పుడు కొడితే బలమైన పంచ్ నక్షత్రం నిండుతుంది.",
  'Esquivar': "తప్పించుకో",
  'Abaixar e defender': "వంగి అడ్డుకో",
  'Socar': "పంచ్ కొట్టు",
  'Soco forte': "బలమైన పంచ్",
  'Aperte os socos para levantar!': "లేవడానికి పంచ్ బటన్లు నొక్కు!",
  'Lutas vencidas: {n}': "గెలిచిన పోరాటాలు: {n}",
  'Nocaute!': "నాకౌట్!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "నక్షత్ర మార్గం",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "అంతరిక్ష నౌకల్లో కుందేళ్లు ఒక గ్రహం ఉపరితలం మీదుగా, అంతరిక్షంలోకి: కాల్చు, లక్ష్యాన్ని లాక్ చేయడానికి కాల్పును నొక్కి పట్టు, తూటాలను తిప్పికొట్టడానికి గిర్రున తిరుగు, చీలికలో దారి ఎంచుకో. జట్టు అదే దారిలో ఎగురుతుంది, చివర్లో బాస్ ఎదురుచూస్తాడు.",
  'Pirueta': "గిర్రు",
  'Segure para travar a mira': "లాక్ చేయడానికి నొక్కి పట్టు",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "క్యారెట్ కమాండో",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "బృందంతో కలిసి పరిగెత్తి కాల్చు: క్యారెట్ తుపాకీ ఎనిమిది దిశల్లో గురిపెడుతుంది, గ్రెనేడ్ దారి తెరుస్తుంది, బోనుల్లో చిక్కిన చిన్న కుందేళ్లను విడిపించినవారికి అదనపు శక్తి వస్తుంది. చివర్లో డ్రాగన్ ఎదురుచూస్తోంది: 1 నుంచి 4 మంది.",
  'Andar e mirar': "నడిచి గురిపెట్టు",
  'Granada': "గ్రెనేడ్",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "తోట పిన్‌బాల్",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "కూరగాయల తోటలో ఒక పిన్‌బాల్ టేబుల్: స్ప్రింగ్‌ను పట్టుకో, క్యాబేజీలకు తగిలి ఎగరనివ్వు, మూడు క్యారెట్లను పడగొట్టి కుందేలు బొరియను వెలిగించు, అది ఇంకో బంతిని వదులుతుంది. మూడు బంతులు, ఎక్కువగా ఊపితే టేబుల్ లాక్ అవుతుంది.",
  'Palhetas': "ఫ్లిప్పర్లు",
