  'Desafios de voo: asa-delta, mochila a jato e paraquedas. Passe pelos anéis e pouse no alvo, perto do centro e de leve.': 'ఎగిరే సవాళ్లు: హ్యాంగ్ గ్లైడర్, జెట్‌ప్యాక్, పారాచూట్. ఉంగరాల గుండా ఎగిరి, లక్ష్యంపై మధ్యకు దగ్గరగా మెల్లగా దిగు.',
