  // Lendas da Toca (16/11/2026)
  'Lendas da Toca': "బొరియ గాథలు",
  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "వంతుల వారీగా ఆడే చిన్న RPG: ప్రతి ఒక్కరూ జట్టులోని ఒక వీరుడిని నడుపుతారు. కలిసి ఎంచుకోండి, దాడులు కలపండి, కోట డ్రాగన్‌ను ఓడించండి.",
