  "A largada precisa de uma reta.": "ప్రారంభ రేఖకు ఒక నేరు దారి కావాలి.",
  "A Maravilha de {nome} ficou de pé por 2 minutos.": "{nome} అద్భుతం 2 నిమిషాలు నిలిచింది.",
  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "ఒకే స్థితి మూడోసారి వస్తే డ్రా; ఏదీ తినకుండా రాజులు మాత్రమే 20 ఎత్తులు వేసినా డ్రా.",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "రాత్రి, తోడేళ్లు ఎవరిపై దాడి చేశాయో చూడండి. ఒక మందు ఆ వ్యక్తిని కాపాడుతుంది, ఇంకొకటి ఒకరిని ఆట నుంచి తీసేస్తుంది; ఒక్కోటి ఒక్కసారే.",
  "A partida se desencontrou entre os computadores e foi encerrada.": "కంప్యూటర్ల మధ్య ఆట సరిపోలలేదు, అందుకే ముగించబడింది.",
  "A pedra que termina o lance na última fileira vira dama, que anda a diagonal inteira.": "చివరి వరుసలో ఎత్తు ముగించే కాయ రాజుగా మారుతుంది; అది కర్ణం పొడవునా కదులుతుంది.",
  "A pista ainda não fecha a volta.": "దారి ఇంకా రౌండ్ పూర్తి చేయడం లేదు.",
  "A pista está curta demais.": "దారి చాలా చిన్నది.",
  "A pista passa por cima dela mesma.": "దారి తన మీదే దాటుతోంది.",
  "A pista precisa de mais peças.": "దారికి ఇంకా ముక్కలు కావాలి.",
  "A turma age antes nas duas rodadas seguintes.": "తదుపరి రెండు రౌండ్లలో జట్టు ముందుగా కదులుతుంది.",
  "A turma está decidindo.": "జట్టు నిర్ణయిస్తోంది.",
