  "Um golpe forte de magia num inimigo só.": "ఒకే శత్రువుపై బలమైన మాయ దెబ్బ.",
  "Um tiro que deixa o inimigo tonto: ele perde a vez.": "శత్రువుకు మైకం తెప్పించే షాట్: అది తన వంతు కోల్పోతుంది.",
