  "Você derrubou o centro da vila de {nome}.": "మీరు {nome} గ్రామ కేంద్రాన్ని కూల్చారు.",
  "Você ficou fora da sala por muito tempo.": "మీరు చాలాసేపు గది బయట ఉన్నారు.",
