  "As duas diagonais também têm os números de 1 a 9.": "రెండు వికర్ణాల్లోనూ 1 నుంచి 9 వరకు అంకెలు ఉంటాయి.",
  "As escuras não fazem dois três abertos de uma vez": "నల్ల కాయలు ఒకేసారి రెండు తెరిచిన మూడులు చేయవు",
  "As escuras não podem fazer dois três abertos de uma vez.": "నల్ల కాయలు ఒకేసారి రెండు తెరిచిన మూడులు చేయలేవు.",
  "Baixa temporada em {lugares}: os aluguéis caem pela metade por uma rodada.": "{lugares}లో మందకొడి సీజన్: ఒక రౌండ్ పాటు అద్దెలు సగం.",
  "Batidas especiais: carroça e lá-e-ló valem o dobro": "ప్రత్యేక గెలుపు: జోడీ రాయి, రెండు చివర్లకు సరిపోయే రాయి రెట్టింపు",
