  "Chuva de estrelas": "నక్షత్రాల వాన",
  "Com a captura, cercar duas pedras do outro entre duas suas tira as duas; cinco capturas também vencem.": "పట్టు నియమంతో, ప్రత్యర్థి రెండు రాళ్లను నీ రెండు రాళ్ల మధ్య చుట్టుముడితే రెండూ పోతాయి; ఐదు పట్లు కూడా గెలిపిస్తాయి.",
  "Com a restrição 3-3, as escuras não podem fazer dois três abertos de uma vez.": "3-3 నిషేధంతో, నల్ల కాయలు ఒకేసారి రెండు తెరిచిన మూడులు చేయలేవు.",
  "Com as batidas especiais, bater com carroça ou com a pedra que serve nas duas pontas vale o dobro; a carroça nas duas pontas, o quádruplo.": "ప్రత్యేక గెలుపుతో, జోడీ రాయితో లేదా రెండు చివర్లకూ సరిపోయే రాయితో ముగిస్తే రెట్టింపు; రెండు చివర్లకూ సరిపోయే జోడీ అయితే నాలుగు రెట్లు.",
