  "No mineiro não há vira: as manilhas são o 4 de paus, o 7 de copas, o ás de espadas e o 7 de ouros.": "మినేరోలో తిప్పిన కార్డు ఉండదు: మనీలాలు క్లబ్స్ 4, హార్ట్స్ 7, స్పేడ్స్ ఏస్, డైమండ్స్ 7.",
  "No mineiro, a mão vale 2, e o truco, o seis, o nove e o doze valem 4, 8, 10 e 12. Com 10 pontos, é a mão de dez: jogar valendo 4, ou correr e dar 2.": "మినేరోలో చేయి విలువ 2; ట్రూకో, ఆరు, తొమ్మిది, పన్నెండు విలువలు 4, 8, 10, 12. 10 పాయింట్ల దగ్గర పదికి చేయి: 4 విలువతో ఆడు, లేదా పారిపోయి 2 ఇవ్వు.",
