  "No tabuleiro de 10 × 10, as internacionais, são 20 pedras de cada lado; a regra é a mesma.": "10 × 10 బోర్డుపై, అంటే అంతర్జాతీయ చెక్కర్స్‌లో, ప్రతి వైపు 20 కాయలు ఉంటాయి; నియమం అదే.",
