  "Quantos segundos tem um minuto?": "ఒక నిమిషంలో ఎన్ని సెకన్లు?",
  "Quatorze": "పద్నాలుగు",
  "Que animal carrega a casa nas costas?": "ఏ జంతువు తన ఇంటిని వీపుపై మోస్తుంది?",
  "Que animal tem listras pretas e brancas?": "ఏ జంతువుకు నలుపు తెలుపు చారలు ఉంటాయి?",
  "Que bicho faz teia?": "ఏ జీవి గూడు అల్లుతుంది?",
  "Que bicho produz mel?": "ఏ జీవి తేనె తయారు చేస్తుంది?",
  "Que fruta é a base do guacamole?": "గ్వాకమోలేకు ఆధారమైన పండు ఏది?",
  "Que fruta é amarela e comprida?": "ఏ పండు పసుపుగా, పొడవుగా ఉంటుంది?",
  "Que gás as plantas soltam no ar?": "మొక్కలు గాలిలోకి ఏ వాయువును విడుదల చేస్తాయి?",
  "Que gás nós soltamos ao respirar?": "శ్వాస వదిలేటప్పుడు మనం ఏ వాయువును విడుదల చేస్తాం?",
  "Que instrumento tem teclas brancas e pretas?": "ఏ వాద్యానికి తెలుపు, నలుపు మీటలు ఉంటాయి?",
  "Que planeta tem anéis bem visíveis?": "ఏ గ్రహానికి స్పష్టంగా కనిపించే వలయాలు ఉంటాయి?",
  "Recorde: {n} lances": "రికార్డు: {n} ఎత్తులు",
  "Rei e dama contra rei": "రాజు, మంత్రితో రాజుపై",
