  "Saara": "సహారా",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "ఒక రహస్య జంతువును ఎంచుతారు, అందరూ ఊహిస్తారు. ప్రతి ఊహ రహస్యంతో ఏది సరిపోతుందో చూపుతుంది: తరగతి, ఆహారం, నివసించే చోటు, బరువు. తక్కువ ఊహల్లో కనిపెట్టినవారికి ఎక్కువ పాయింట్లు.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "ఒక రహస్య డైనోసార్‌ను ఎంచుతారు, అందరూ ఊహిస్తారు. ప్రతి ఊహ రహస్యంతో ఏది సరిపోతుందో చూపుతుంది: కాలం, ఆహారం, సమూహం, పొడవు, అది దొరికిన చోటు. తక్కువ ఊహల్లో కనిపెట్టినవారికి ఎక్కువ పాయింట్లు.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "ఒక రహస్య రసాయన మూలకాన్ని ఎంచుతారు, అందరూ ఊహిస్తారు. ప్రతి ఊహ రహస్యంతో ఏది సరిపోతుందో చూపుతుంది: కుటుంబం, భౌతిక స్థితి, పీరియడ్, గ్రూప్, పరమాణు సంఖ్య. తక్కువ ఊహల్లో కనిపెట్టినవారికి ఎక్కువ పాయింట్లు.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "బ్రెజిల్‌లోని ఒక రహస్య రాష్ట్రాన్ని ఎంచుతారు, అందరూ ఊహిస్తారు. ప్రతి ఊహ రహస్యం వరకు దూరం, దిశ, ప్రాంతం, జనాభా, విస్తీర్ణం, తీరం, వేరే దేశంతో సరిహద్దు చూపుతుంది. తక్కువ ఊహల్లో కనిపెట్టినవారికి ఎక్కువ పాయింట్లు.",
