  "Você joga por conta própria: vence se a vila tirar você do jogo no julgamento. Levante suspeitas, mas sem exagero.": "నువ్వు నీ కోసమే ఆడతావు: విచారణలో గ్రామం నిన్ను ఆట నుంచి తొలగిస్తే నువ్వు గెలుస్తావు. అనుమానం రేకెత్తించు, కానీ మితిమీరకుండా.",
