  "Editar mensagem": "సందేశాన్ని సవరించు",
  "Canal de avisos: só quem administra escreve aqui. Para conversar sobre um aviso, abra um tópico nele.": "ప్రకటనల ఛానెల్: ఇక్కడ నిర్వహించేవారు మాత్రమే రాస్తారు. ఒక ప్రకటన గురించి మాట్లాడాలంటే, దానిపై ఒక థ్రెడ్ తెరవండి.",
  "Canais de avisos": "ప్రకటనల ఛానెల్‌లు",
  "Num canal de avisos, só quem administra escreve. A turma lê, reage e conversa nos tópicos de cada aviso.": "ప్రకటనల ఛానెల్‌లో నిర్వహించేవారు మాత్రమే రాస్తారు. మిగతావారు చదువుతారు, స్పందిస్తారు, ప్రతి ప్రకటన థ్రెడ్‌లలో మాట్లాడుకుంటారు.",
