  "Tirar o status": "స్థితిని తీసివేయి",
  "Neste canal de avisos, só quem administra escreve. Dá para responder num tópico.": "ఈ ప్రకటనల ఛానెల్‌లో నిర్వహించేవారు మాత్రమే రాస్తారు. మీరు థ్రెడ్‌లో జవాబు ఇవ్వవచ్చు.",
  "Só canal de texto vira canal de avisos.": "టెక్స్ట్ ఛానెల్ మాత్రమే ప్రకటనల ఛానెల్‌గా మారగలదు.",
  "Só quem escreveu a mensagem pode editá-la.": "సందేశాన్ని రాసినవారు మాత్రమే దాన్ని సవరించగలరు.",
  "Esta mensagem não tem texto para editar.": "ఈ సందేశంలో సవరించడానికి టెక్స్ట్ లేదు.",
  "A mensagem não pode ficar vazia. Para tirá-la, apague.": "సందేశం ఖాళీగా ఉండకూడదు. దాన్ని తీసివేయాలంటే, తొలగించండి.",
  "Este convite expirou.": "ఈ ఆహ్వానం గడువు ముగిసింది.",
  "Este convite já foi usado o máximo de vezes.": "ఈ ఆహ్వానం ఇప్పటికే గరిష్ఠ సార్లు వాడబడింది.",
  "Escolha uma validade e um limite de usos da lista.": "జాబితా నుంచి ఒక చెల్లుబాటును, ఒక వాడకాల పరిమితిని ఎంచుకోండి.",
  "Você já tem convites demais nesta comunidade. Revogue algum antes de criar outro.": "ఈ కమ్యూనిటీలో మీకు ఇప్పటికే చాలా ఆహ్వానాలు ఉన్నాయి. ఇంకొకటి సృష్టించే ముందు ఒకదాన్ని రద్దు చేయండి.",
  "Convite não encontrado.": "ఆహ్వానం కనబడలేదు.",
  "Só quem criou o convite, ou quem administra a comunidade, pode revogá-lo.": "ఆహ్వానాన్ని సృష్టించినవారు, లేదా కమ్యూనిటీని నిర్వహించేవారు మాత్రమే దాన్ని రద్దు చేయగలరు.",
  "Só quem administra a comunidade vê o registro de moderação.": "కమ్యూనిటీని నిర్వహించేవారు మాత్రమే పర్యవేక్షణ రికార్డును చూడగలరు.",
  "Só quem está na sala muda o status dela.": "గదిలో ఉన్నవారు మాత్రమే దాని స్థితిని మార్చగలరు.",
  "O status da sala tem no máximo 60 caracteres.": "గది స్థితి గరిష్ఠంగా 60 అక్షరాలు ఉండవచ్చు.",
  "A sala está vazia: o status só aparece com alguém nela.": "గది ఖాళీగా ఉంది: ఎవరైనా ఉన్నప్పుడే స్థితి కనిపిస్తుంది.",
  "Esta comunidade não permite uma das palavras deste status.": "ఈ కమ్యూనిటీ ఈ స్థితిలోని ఒక పదాన్ని అనుమతించదు.",
  "Esta comunidade não permite links no status da sala.": "ఈ కమ్యూనిటీ గది స్థితిలో లింక్‌లను అనుమతించదు.",
  "Espere alguns segundos para mudar o status da sala de novo.": "గది స్థితిని మళ్లీ మార్చడానికి కొన్ని సెకన్లు ఆగండి.",
